	private static Set<Statement> initialRows() {
		Set<Statement> result = new LinkedHashSet<>();
		for (int seed = 0; seed < LOADED.size(); seed++) {
			for (IRI graph : List.of(FIRST, SECOND)) {
				result.add(VF.createStatement(VF.createIRI(BASE + "loaded-" + seed), predicate(seed), LOADED.get(seed),
						graph));
			}
		}
		return result;
	}

