	private static void assertSafeDomains(Opened opened, Profile profile) throws Exception {
		LmdbSailStore backing = opened.store().getBackingStore();
		LmdbEstimatorRuntime runtime = ((LmdbEvaluationStatistics) opened.store()
				.getSailStore()
				.getEvaluationStatistics()).estimatorRuntime();
		// Persisted and known domain authority is served only inside a pinned planning view of one paired snapshot.
		try (LmdbSailStore.DatasetAdmission view = backing.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null)) {
			view.view().requireDictionaryTermSnapshot();
			try (TripleStore.PlanningReadPin ignored = runtime.pinPlanningReads(view.view().tripleTxn(),
					view.view().valueSnapshot())) {
				assertSafeDomainsInPinnedView(opened, profile, backing);
			}
		}
	}

	private static void assertSafeDomainsInPinnedView(Opened opened, Profile profile, LmdbSailStore backing)
			throws Exception {
		ValueStore values = (ValueStore) backing.getValueFactory();
		for (int seed = 0; seed < LOADED.size(); seed++) {
			IRI predicate = predicate(seed);
			Optional<RdfTermDomain> cached = backing.getCachedRdfTermDomain(predicate);
			Optional<RdfTermDomain> persisted = backing.getPersistedRdfTermDomain(predicate);
			Optional<RdfTermDomain> known = backing.getTripleStore().getKnownRdfTermDomain(values.getId(predicate));
			String servedVersion = backing.getTripleStore().effectiveRdfTermDomainsVersion();
			boolean disabled = servedVersion.endsWith("-disabled");
			boolean readable = !disabled && !servedVersion.endsWith("-unreadable");
			boolean excluded = opened.config()
					.getPredicateGuaranteeExcludedPredicateSet()
					.contains(predicate.stringValue());
			assertEquals(!opened.config().getPredicateGuaranteeIndexEnabled(), disabled,
					"served disabled authority must match the actual opener configuration: " + profile);
			assertEquals(persisted, known, "readable persisted and known guarantees agree: " + predicate);
			if (!readable || excluded) {
				assertEquals(Optional.empty(), persisted, "unqualified persisted metadata must not be served");
				assertEquals(Optional.empty(), known, "unqualified metadata has no readable authority");
			} else {
				assertEquals(persisted, cached,
						"readable committed cache agrees with persisted metadata: " + predicate);
			}
			if (known.isPresent() && !known.get().isUnknown()
					&& !known.get().equals(RdfTermDomain.UNRESTRICTED)) {
				RdfTermDomain domain = known.get();
				assertFalse(domain.has(RdfTermDomain.Fact.CANONICAL_INTEGER),
						"a later canonical value cannot erase old IRI/string/noncanonical/triple-term owners: "
								+ predicate);
				assertFalse(domain.isEmpty(), "a live old owner remains in the second context");
				if (seed == 0) {
					assertTrue(domain.has(RdfTermDomain.Fact.IRI), "the old IRI must remain possible");
				} else if (seed == 1 || seed == 2) {
					assertTrue(domain.has(RdfTermDomain.Fact.LITERAL), "the old literal must remain possible");
				}
			}
		}
	}

	/**
	 * Writes the loaded rows as a prepared format-7 bulk generation with predicate guarantees disabled. Such output has
	 * no predicate-object domain authority, like historical pre-domain output, so every later opener must rebuild,
	 * withhold, or disable domains instead of trusting absent or stale facts.
	 */
	private static void generateDomainlessBulkStore(boolean inline, Path target) throws Exception {
		List<Statement> input = new ArrayList<>(initialRows());
		// Repeated input rows exercise the loader's set semantics, as in the historical capture input.
		input.addAll(initialRows());
		ByteArrayOutputStream encoded = new ByteArrayOutputStream();
		Rio.write(input, encoded, RDFFormat.NQUADS);
		LmdbBulkLoader.builder(target, config(inline, Profile.DISABLED, false))
				.partitionCount(4)
				.workers(1)
				// Not a low-memory test: a budget below the loader's fixed buffers (about 2.6 MiB) leaves the
				// sorters one record per run and makes this load take minutes.
				.memoryBudgetBytes(64L * 1024 * 1024)
				.maxOpenFiles(16)
				.build()
				.load(new ByteArrayInputStream(encoded.toByteArray()), BASE, RDFFormat.NQUADS);
		Properties written = LmdbCompatibilityFixtures.properties(target, StoreProperties.FILE_NAME);
		assertEquals(Integer.toString(LmdbStoreFormat.CURRENT_VERSION), written.getProperty("version"));
		assertEquals(Boolean.toString(inline), written.getProperty(StoreProperties.INLINE_LITERALS_KEY));
		assertFalse(Files.exists(target.resolve(".lmdb-bulk-load.incomplete")));
		assertTrue(Files.isRegularFile(target.resolve(".lmdb-bulk-prepared")));
		// Fail loudly if the loader starts publishing domains for this profile: the cases would then test nothing.
		assertNull(written.getProperty(StoreProperties.RDF_TERM_DOMAIN_QUALIFICATION_KEY),
				"the generated bulk output must carry no domain qualification witness");
		assertEquals(0L, nativeTripleEntryCountOrZero(target, TripleStore.PREDICATE_OBJECT_DOMAINS_DB),
				"the generated bulk output must contain no predicate-object domain records");
	}

	private static long nativeTripleEntryCountOrZero(Path target, String database) throws Exception {
		try {
			return LmdbCompatibilityFixtures.nativeTripleEntryCount(target, database);
		} catch (LmdbUtil.LmdbException missing) {
			assertEquals(MDB_NOTFOUND, missing.errorCode, "only an absent database may count as empty");
			return 0L;
		}
	}

	private static void assertQueryBags(Opened opened, Set<Statement> statements) {
		EvaluationStrategyFactory previous = opened.store().getEvaluationStrategyFactory();
		assertInstanceOf(LmdbEvaluationStrategyFactory.class, previous);
		try {
			for (boolean nativeEngine : new boolean[] { false, true }) {
				opened.store()
						.setEvaluationStrategyFactory(nativeEngine
								? new LmdbNativeEvaluationStrategyFactory(opened.store().getFederatedServiceResolver())
								: previous);
				authenticateExecutionPolicy(opened, nativeEngine);
				List<QueryCase> queries = List.of(new QueryCase("", value -> true),
						new QueryCase("isIRI(?o)", value -> value instanceof IRI),
						new QueryCase("isLiteral(?o)", value -> value instanceof Literal),
						new QueryCase("!isLiteral(?o)", value -> !(value instanceof Literal)),
						new QueryCase("isNumeric(?o)", LmdbHistoricalBulkDomainCompatibilityTest::numeric),
						new QueryCase("?o = 7", value -> numeric(value) && ((Literal) value).intValue() == 7),
						new QueryCase("LANG(?o) = \"en\"", value -> value instanceof Literal literal
								&& literal.getLanguage().filter("en"::equals).isPresent()));
				for (int scope = -1; scope < LOADED.size(); scope++) {
					for (QueryCase query : queries) {
						Map<Row, Long> expected = new HashMap<>();
						for (Statement statement : statements)
							if ((scope < 0 || predicate(scope).equals(statement.getPredicate()))
									&& query.matches().test(statement.getObject())) {
								expected.merge(
										row(statement.getSubject(), statement.getPredicate(), statement.getObject(),
												statement.getContext()),
										2L, Long::sum);
							}
						String pattern = scope < 0 ? "GRAPH ?g { ?s ?p ?o } "
								: "GRAPH ?g { ?s <" + predicate(scope) + "> ?o } BIND(<" + predicate(scope)
										+ "> AS ?p) ";
						String sparql = "SELECT ?s ?p ?o ?g WHERE { VALUES ?duplicate { 1 1 } " + pattern
								+ (query.filter().isEmpty() ? "" : "FILTER(" + query.filter() + ")") + " }";
						Map<Row, Long> actual = new HashMap<>();
						try (var connection = opened.repository().getConnection();
								var results = connection.prepareTupleQuery(sparql).evaluate()) {
							while (results.hasNext()) {
								var bindings = results.next();
								actual.merge(row(bindings.getValue("s"), bindings.getValue("p"), bindings.getValue("o"),
										bindings.getValue("g")), 1L, Long::sum);
							}
						}
						assertEquals(expected, actual, "public full bags: native=" + nativeEngine + ", experimental="
								+ opened.experimental() + "; " + sparql);
					}
				}
			}
		} finally {
			opened.store().setEvaluationStrategyFactory(previous);
		}
	}

	private static void authenticateExecutionPolicy(Opened opened, boolean nativeEngine) {
		LmdbStore store = opened.store();
		assertEquals(nativeEngine, store.isNativeQueryEngineEnabled());
		assertEquals(QueryExecutionPolicy.of(opened.experimental()), store.getQueryExecutionPolicy());
		try (SailDataset dataset = store.getBackingStore()
				.getExplicitSailSource()
				.dataset(IsolationLevels.SNAPSHOT_READ)) {
			SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(store.getValueFactory(), dataset);
			assertTrue(source.getSnapshotEpoch().isPresent());
			var strategy = store.getConnectionEvaluationStrategyFactory()
					.createEvaluationStrategy(null, source,
							new EvaluationStatistics(), store.getQueryExecutionPolicy());
			assertInstanceOf(LmdbEvaluationStrategy.class, strategy);
			if (nativeEngine)
				assertInstanceOf(LmdbNativeEvaluationStrategy.class, strategy);
			else
				assertFalse(strategy instanceof LmdbNativeEvaluationStrategy);
			assertEquals(QueryExecutionPolicy.of(opened.experimental()), strategy.getQueryExecutionPolicy());
		}
	}

	private static boolean numeric(Value value) {
		return value instanceof Literal literal && literal.getCoreDatatype().asXSDDatatypeOrNull() != null
				&& literal.getCoreDatatype().asXSDDatatypeOrNull().isNumericDatatype();
	}

	private static Row row(Value subject, Value predicate, Value object, Value graph) {
		return new Row(NTriplesUtil.toNTriplesString(subject), NTriplesUtil.toNTriplesString(predicate),
				NTriplesUtil.toNTriplesString(object), NTriplesUtil.toNTriplesString(graph));
	}
